import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  Box,
  Container,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Fab,
  AppBar,
  Toolbar,
  IconButton,
  Badge,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import {
  Emergency,
  LocationOn,
  Chat,
  History,
  Settings,
  Notifications,
  Menu,
  Person,
} from '@mui/icons-material';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

import { sendEmergencyAlert, getSafetyLocations } from '../store/slices/emergencySlice';
import { updateLocation } from '../store/slices/userSlice';
import emergencyService from '../services/emergencyService';
import socketService from '../services/socketService';

// Fix leaflet default markers
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const Dashboard = () => {
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.auth);
  const { safetyLocations, isSendingAlert } = useSelector((state) => state.emergency);

  const [currentLocation, setCurrentLocation] = useState(null);
  const [emergencyDialog, setEmergencyDialog] = useState(false);
  const [shakeDetection, setShakeDetection] = useState(false);
  const [lastShake, setLastShake] = useState(0);

  useEffect(() => {
    // Get current location
    getCurrentLocation();

    // Set up shake detection
    if (user?.preferences?.shakeDetection) {
      setupShakeDetection();
    }

    // Get nearby safety locations
    if (currentLocation) {
      dispatch(getSafetyLocations({
        latitude: currentLocation.latitude,
        longitude: currentLocation.longitude,
        radius: 5000,
      }));
    }
  }, [dispatch, user, currentLocation]);

  const getCurrentLocation = async () => {
    try {
      const location = await emergencyService.getCurrentLocation();
      setCurrentLocation(location);

      // Update user location in backend
      const address = await emergencyService.reverseGeocode(
        location.latitude,
        location.longitude
      );

      dispatch(updateLocation({
        latitude: location.latitude,
        longitude: location.longitude,
        address,
      }));
    } catch (error) {
      console.error('Failed to get location:', error);
    }
  };

  const setupShakeDetection = () => {
    if (typeof DeviceMotionEvent !== 'undefined') {
      window.addEventListener('devicemotion', handleDeviceMotion);
      setShakeDetection(true);
    }
  };

  const handleDeviceMotion = (event) => {
    const { accelerationIncludingGravity } = event;
    if (!accelerationIncludingGravity) return;

    const { x, y, z } = accelerationIncludingGravity;
    const acceleration = Math.sqrt(x * x + y * y + z * z);

    // Detect shake (threshold can be adjusted)
    if (acceleration > 20) {
      const now = Date.now();
      if (now - lastShake > 3000) { // Prevent multiple triggers
        setLastShake(now);
        handleEmergencyAlert('shake');
      }
    }
  };

  const handleEmergencyAlert = async (type = 'manual') => {
    if (!currentLocation) {
      alert('Location not available. Please enable location services.');
      return;
    }

    const alertData = {
      type,
      latitude: currentLocation.latitude,
      longitude: currentLocation.longitude,
      message: `Emergency alert triggered via ${type}`,
      severity: 'high',
    };

    try {
      await dispatch(sendEmergencyAlert(alertData));
      setEmergencyDialog(true);

      // Vibrate if supported
      if (navigator.vibrate) {
        navigator.vibrate([200, 100, 200, 100, 200]);
      }
    } catch (error) {
      console.error('Failed to send emergency alert:', error);
    }
  };

  const quickActions = [
    {
      icon: <Chat />,
      label: 'AI Assistant',
      path: '/chat',
      color: 'secondary',
    },
    {
      icon: <History />,
      label: 'Alert History',
      path: '/alert-history',
      color: 'info',
    },
    {
      icon: <Person />,
      label: 'Emergency Contacts',
      path: '/emergency-contacts',
      color: 'warning',
    },
    {
      icon: <Settings />,
      label: 'Settings',
      path: '/settings',
      color: 'default',
    },
  ];

  return (
    <Box>
      {/* App Bar */}
      <AppBar position="static" elevation={0}>
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            Welcome, {user?.fullName?.split(' ')[0]}
          </Typography>
          <IconButton color="inherit">
            <Badge badgeContent={0} color="error">
              <Notifications />
            </Badge>
          </IconButton>
          <IconButton color="inherit">
            <Menu />
          </IconButton>
        </Toolbar>
      </AppBar>

      <Container maxWidth="lg" sx={{ py: 3 }}>
        <Grid container spacing={3}>
          {/* Emergency Button */}
          <Grid item xs={12}>
            <Card sx={{ textAlign: 'center', py: 4, background: 'linear-gradient(135deg, #ff6b9d 0%, #c53975 100%)' }}>
              <CardContent>
                <Typography variant="h5" color="white" mb={3}>
                  Emergency SOS
                </Typography>
                <Fab
                  className="emergency-button pulse"
                  onClick={() => handleEmergencyAlert('manual')}
                  disabled={isSendingAlert}
                  sx={{
                    width: 120,
                    height: 120,
                    background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
                    '&:hover': {
                      background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
                      transform: 'scale(1.05)',
                    },
                  }}
                >
                  <Emergency sx={{ fontSize: 40, color: 'white' }} />
                </Fab>
                <Typography variant="body2" color="white" mt={2}>
                  {isSendingAlert ? 'Sending Alert...' : 'Tap for Emergency'}
                </Typography>
                {shakeDetection && (
                  <Typography variant="caption" color="white" display="block" mt={1}>
                    Shake detection: ON
                  </Typography>
                )}
              </CardContent>
            </Card>
          </Grid>

          {/* Location Map */}
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  <LocationOn color="primary" sx={{ mr: 1, verticalAlign: 'middle' }} />
                  Your Location & Nearby Safety Points
                </Typography>
                <Box className="map-container">
                  {currentLocation ? (
                    <MapContainer
                      center={[currentLocation.latitude, currentLocation.longitude]}
                      zoom={13}
                      style={{ height: '300px', width: '100%' }}
                    >
                      <TileLayer
                        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                      />
                      <Marker position={[currentLocation.latitude, currentLocation.longitude]}>
                        <Popup>Your current location</Popup>
                      </Marker>
                      {safetyLocations.map((location, index) => (
                        <Marker
                          key={index}
                          position={[location.location.latitude, location.location.longitude]}
                        >
                          <Popup>
                            <strong>{location.name}</strong><br />
                            {location.type}<br />
                            Distance: {Math.round(location.distance)}m
                          </Popup>
                        </Marker>
                      ))}
                    </MapContainer>
                  ) : (
                    <Box
                      display="flex"
                      justifyContent="center"
                      alignItems="center"
                      height={300}
                      bgcolor="grey.100"
                    >
                      <Typography color="text.secondary">
                        Getting your location...
                      </Typography>
                    </Box>
                  )}
                </Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Quick Actions */}
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  Quick Actions
                </Typography>
                <Grid container spacing={2}>
                  {quickActions.map((action, index) => (
                    <Grid item xs={6} key={index}>
                      <Button
                        fullWidth
                        variant="outlined"
                        color={action.color}
                        startIcon={action.icon}
                        onClick={() => window.location.href = action.path}
                        sx={{ py: 2, flexDirection: 'column', gap: 1 }}
                      >
                        {action.label}
                      </Button>
                    </Grid>
                  ))}
                </Grid>
              </CardContent>
            </Card>
          </Grid>

          {/* Safety Tips */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" mb={2}>
                  Daily Safety Tips
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  • Always share your location with trusted contacts when going out
                  • Trust your instincts - if something feels wrong, seek help immediately
                  • Keep your phone charged and emergency contacts updated
                  • Use well-lit and populated routes when walking alone
                  • Consider using the NIVRA AI assistant for safety guidance
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>

      {/* Emergency Alert Dialog */}
      <Dialog open={emergencyDialog} onClose={() => setEmergencyDialog(false)}>
        <DialogTitle>Emergency Alert Sent!</DialogTitle>
        <DialogContent>
          <Typography>
            Your emergency alert has been sent to your emergency contacts and nearby users.
            Help is on the way. Stay safe!
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEmergencyDialog(false)} color="primary">
            OK
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default Dashboard;
